test_traj.command:
cd /tmp/rev && cat <<'EOF' > up.ll
define i32 @ashr_cttz_false(i32 %x, i32 %y) {
  %cttz = call i32 @llvm.cttz.i32(i32 %y, i1 false)
  %res = ashr i32 %x, %cttz
  ret i32 %res
}
define i32 @shl_cttz_false_multiuse(i32 %x, i32 %y) {
  %cttz = call i32 @llvm.cttz.i32(i32 %y, i1 false)
  call void @use(i32 %cttz)
  %res = shl i32 %x, %cttz
  ret i32 %res
}
define i32 @shl_cttz_false(i32 %x, i32 %y) {
  %cttz = call i32 @llvm.cttz.i32(i32 %y, i1 false)
  %res = shl i32 %x, %cttz
  ret i32 %res
}
define i32 @shl_ctlz_false(i32 %x, i32 %y) {
  %ctlz = call i32 @llvm.ctlz.i32(i32 %y, i1 false)
  %res = shl i32 %x, %ctlz
  ret i32 %res
}
define i32 @shl_cttz_as_lhs(i32 %x, i32 %y) {
  %cttz = call i32 @llvm.cttz.i32(i32 %y, i1 false)
  %res = shl i32 %cttz, %x
  ret i32 %res
}
define i32 @lshr_cttz_false(i32 %x, i32 %y) {
  %cttz = call i32 @llvm.cttz.i32(i32 %y, i1 false)
  %res = lshr i32 %x, %cttz
  ret i32 %res
}
declare void @use(i32)
declare i32 @llvm.cttz.i32(i32, i1)
declare i32 @llvm.ctlz.i32(i32, i1)
EOF
opt -S -passes=instcombine up.ll -o up.out.ll && alive-tv up.ll up.out.ll 2>&1 | tail -6; echo "=== resulting IR:"; grep -n "ctlz\|cttz\|shl\|ashr\|lshr" up.out.ll | head -30
